import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written fake of the downstream pricing service (unit price in euros).
const prices = { A: 10, B: 40, C: 33.33, D: 101, FREE: 0 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order, 201, priced via pricing service', async () => {
  calls.length = 0
  const r = await json(await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'FREE', qty: 1 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.match(r.body.id, /^\d+$/)
  assert.deepEqual(r.body.items, [{ sku: 'A', qty: 2 }, { sku: 'FREE', qty: 1 }])
  assert.equal(r.body.total, 20)
  assert.deepEqual(calls, ['A', 'FREE'])
  assert.deepEqual(Object.keys(r.body).sort(), ['id', 'items', 'total'])
})

test('POST /orders ids are sequential strings', async () => {
  const a = await json(await post({ items: [{ sku: 'A', qty: 1 }] }))
  const b = await json(await post({ items: [{ sku: 'A', qty: 1 }] }))
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
  assert.equal(typeof a.body.id, 'string')
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  const r = await json(await post({ items: [{ sku: 'A', qty: 10 }] }))
  assert.equal(r.body.total, 100)
})

test('POST /orders: total above 100 gets 10% discount', async () => {
  const r = await json(await post({ items: [{ sku: 'B', qty: 3 }] }))
  assert.equal(r.body.total, 108)
})

test('POST /orders: total is floored, not rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 101 * 0.9 = 90.9 is floored to 90, and 99.99 to 99 (customer is charged whole euros, cents dropped)
  assert.equal((await json(await post({ items: [{ sku: 'D', qty: 1 }] }))).body.total, 90)
  assert.equal((await json(await post({ items: [{ sku: 'C', qty: 3 }] }))).body.total, 99)
})

test('POST /orders: missing or empty items -> 400', async () => {
  for (const body of [{}, { items: [] }, { items: 'A' }, { items: null }]) {
    const r = await json(await post(body))
    assert.deepEqual(r, { status: 400, type: 'application/json', body: { error: 'items required' } })
  }
})

test('POST /orders: empty body or invalid JSON -> 400', async () => {
  assert.equal((await post(null, '')).status, 400)
  const r = await json(await post(null, '{not json'))
  assert.deepEqual(r, { status: 400, type: 'application/json', body: { error: 'items required' } })
  assert.equal((await post(null, 'null')).status, 400)
})

test('POST /orders: item without qty yields a null total but still 201', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no item validation; undefined qty gives NaN, serialised as null
  const r = await json(await post({ items: [{ sku: 'A' }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders: unknown sku (pricing returns undefined) yields null total, 201', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — unpriced sku is accepted, total becomes null
  const r = await json(await post({ items: [{ sku: 'NOPE', qty: 1 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

