  const r = await json(await fetch(`${base}/orders/99999`))
  assert.deepEqual(r, { status: 200, type: 'application/json', body: { error: 'not found' } })
})

test('unmatched routes -> 404 no route', async () => {
  const cases = [['GET', '/orders'], ['GET', '/'], ['GET', '/orders/1/extra'], ['POST', '/orders/1'],
    ['DELETE', '/orders/1'], ['PUT', '/orders'], ['GET', '/other']]
  for (const [method, path] of cases) {
    const r = await json(await fetch(base + path, { method }))
    assert.deepEqual(r, { status: 404, type: 'application/json', body: { error: 'no route' } }, `${method} ${path}`)
  }
})

